const test = require('node:test');
const assert = require('node:assert/strict');
const { topK } = require('./topk');

test('most frequent first', () => {
  assert.deepEqual(topK(['b', 'a', 'b', 'c', 'a', 'b'], 2), ['b', 'a']);
});

test('k larger than the number of distinct strings', () => {
  assert.deepEqual(topK(['x', 'y', 'x'], 5), ['x', 'y']);
});

test('alphabetical tie-breaking', () => {
  // 'B' comes before 'a' in UTF-16 code unit order
  assert.deepEqual(topK(['a', 'B', 'a', 'B'], 2), ['B', 'a']);
});

test('k equals 0', () => {
  assert.deepEqual(topK(['a', 'b'], 0), []);
});

test('validation of k', () => {
  assert.throws(() => topK(['a'], -1), RangeError);
  assert.throws(() => topK(['a'], 1.5), RangeError);
  assert.throws(() => topK(['a'], '1'), RangeError);
});

test('validation of items', () => {
  assert.throws(() => topK('not an array', 1), TypeError);
  assert.throws(() => topK([1, 2], 1), TypeError);
});
"}
